def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n <= 2:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_def = op.count('D')
    my_def = my.count('D')
    last_my = my[-1]
    last_op = op[-1]

    # Pure cooperator: keep cooperating, only defect in final rounds
    if opp_def == 0:
        if n >= 98:
            return 'D'
        return 'C'

    # Recent opponent cooperation streak
    streak_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            streak_c += 1
        else:
            break

    # Recent opponent defection streak
    streak_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak_d += 1
        else:
            break

    # Endgame: exploit confirmed cooperators, but defend against retaliators
    if n >= 95:
        if opp_def <= 2:
            return 'D'
        if streak_d >= 2:
            return 'D'
        if streak_c >= 3:
            return 'D'
        if last_op == 'C':
            return 'C'
        return 'D'

    # Very cooperative opponent: maintain mutual cooperation
    if opp_def * 8 <= n:
        # If both stayed coop for a while, mostly stay
        if streak_c >= 2:
            return 'C'
        if last_op == 'C':
            return 'C'
        # Opponent just defected after long coop streak - retaliate briefly
        if last_op == 'D' and streak_d <= 1:
            return 'D'

    # Very defection-heavy opponent: defect, but probe for change
    if opp_def * 4 > n * 3:
        if streak_c >= 3:
            return 'C'
        if last_op == 'C' and rng.random() < 0.4:
            return 'C'
        return 'D'

    # Moderate: tit-for-tat with controlled forgiveness
    if last_op == 'D':
        # If we've also been defecting a while, try to break DD loop
        if my[-1] == 'D' and streak_d >= 2:
            # Count opponent defections in last 5
            recent_window = min(5, n)
            recent_opp_d = 0
            for i in range(n - recent_window, n):
                if op[i] == 'D':
                    recent_opp_d += 1
            if recent_opp_d <= 2 and rng.random() < 0.35:
                return 'C'
            return 'D'
        # Opponent defected after our cooperation: punish but watch for reconciliation
        if streak_d >= 3:
            recent_opp_c = 0
            cnt = 0
            for i in range(n - 1, -1, -1):
                if op[i] == 'C':
                    recent_opp_c += 1
                cnt += 1
                if cnt >= 8:
                    break
            if recent_opp_c >= 2 and rng.random() < 0.3:
                return 'C'
        return 'D'

    # last_op == 'C'
    if last_my == 'D':
        # We defected, they cooperated - if opponent forgiving, might exploit,
        # but safer to return to cooperation to avoid triggering retaliation
        if opp_def * 5 <= n:
            return 'C'
        # Opponent somewhat tolerant -> cautiously continue
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    # Both cooperated last round
    # Occasionally probe against tolerant opponents, but rarely
    if n > 10 and opp_def * 10 <= n and rng.random() < 0.02:
        return 'D'
    return 'C'
